          }

          if (statusMessage.textContent) {
            statusMessage.textContent = "";
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        statusMessage.textContent = "";

        const firstInvalidField = fields.find((field) => validateField(field));

        if (firstInvalidField) {
          firstInvalidField.input.focus();
          return;
        }

        statusMessage.textContent = "Your request is ready to send. Our support team will reply soon.";
        form.reset();

        fields.forEach((field) => {
          field.error.hidden = true;
          field.error.textContent = "";
          field.input.removeAttribute("aria-invalid");
          setDescribedBy(field.input, field.helpId, field.error.id, false);
