         min-height: 1.5rem;
         margin-top: 1rem;
         font-weight: 600;
         color: var(--accent-strong);
       }

       @media (min-width: 760px) {
         .hero {
           grid-template-columns: 1.1fr 0.9fr;
         }

         .contact-card {
           margin-top: 0;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           animation: none !important;
           transition: none !important;
           scroll-behavior: auto !important;
         }
       }

       @media (forced-colors: active) {
         .skip-link,
         .contact-card,
         input,
         button {
           forced-color-adjust: auto;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>

     <main id="maincontent" class="page-shell" tabindex="-1">
       <section class="hero" aria-labelledby="support-title">
         <div class="hero-copy">
           <p class="eyebrow">Support</p>
           <h1 id="support-title">Contact our support team</h1>
           <p>
             Share your details and we will follow up with the right specialist as soon as possible.
             Use the phone field only if you would like a call back.
           </p>
         </div>

         <section class="contact-card" aria-labelledby="form-title">
           <h2 id="form-title">Send a support request</h2>
           <p class="card-copy">
             Fields marked with <span class="required-mark" aria-hidden="true">*</span> are required.
           </p>

           <form id="support-form" novalidate>
             <div class="form-grid">
               <div class="form-field">
                 <label for="full-name">
                   Full name <span class="required-mark" aria-hidden="true">*</span>
                 </label>
                 <input
                   id="full-name"
                   name="fullName"
                   type="text"
                   autocomplete="name"
                   required
                 />
                 <p class="field-error" id="full-name-error" hidden></p>
               </div>

               <div class="form-field">
                 <label for="email-address">
                   Email address <span class="required-mark" aria-hidden="true">*</span>
                 </label>
                 <input
                   id="email-address"
                   name="email"
                   type="email"
                   autocomplete="email"
                   required
                 />
                 <p class="field-error" id="email-address-error" hidden></p>
               </div>

               <div class="form-field">
                 <label for="phone-number">Phone number (optional)</label>
                 <input
                   id="phone-number"
                   name="phone"
                   type="tel"
                   inputmode="tel"
                   autocomplete="tel"
                   aria-describedby="phone-number-help"
                 />
                 <p class="field-help" id="phone-number-help">
                   Expected format: use digits with optional spaces or symbols, for example
                   (555) 123-4567 or +1 555 123 4567.
                 </p>
                 <p class="field-error" id="phone-number-error" hidden></p>
               </div>
             </div>

             <div class="actions">
               <button type="submit">Send request</button>
             </div>

             <p class="form-status" id="form-status" aria-live="polite"></p>
           </form>
         </section>
       </section>
     </main>

     <script>
       const form = document.getElementById("support-form");
       const statusMessage = document.getElementById("form-status");

       const fields = [
         {
           input: document.getElementById("full-name"),
           error: document.getElementById("full-name-error"),
           helpId: "",
           validate(value) {
             return value.trim()
               ? ""
               : "Error: Enter your full name so we know who to contact.";
           },
         },
         {
           input: document.getElementById("email-address"),
           error: document.getElementById("email-address-error"),
           helpId: "",
           validate(value) {
             if (!value.trim()) {
               return "Error: Enter your email address so we can reply.";
             }

             return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
               ? ""
               : "Error: Enter a valid email address, like name@example.com.";
           },
         },
         {
           input: document.getElementById("phone-number"),
           error: document.getElementById("phone-number-error"),
           helpId: "phone-number-help",
           validate(value) {
             if (!value.trim()) {
               return "";
             }

             return /^\+?[0-9()\-\s]{7,20}$/.test(value)
               ? ""
               : "Error: Enter a phone number using digits and common separators only.";
           },
         },
       ];

       const setDescribedBy = (input, helpId, errorId, hasError) => {
         const describedBy = [helpId, hasError ? errorId : ""].filter(Boolean).join(" ");
         if (describedBy) {
           input.setAttribute("aria-describedby", describedBy);
         } else {
           input.removeAttribute("aria-describedby");
         }
       };

       const showFieldError = (field, message) => {
         const hasError = Boolean(message);
         field.error.textContent = message;
         field.error.hidden = !hasError;
         if (hasError) {
           field.input.setAttribute("aria-invalid", "true");
         } else {
           field.input.removeAttribute("aria-invalid");
         }
         setDescribedBy(field.input, field.helpId, field.error.id, hasError);
         return hasError;
       };

       const validateField = (field) => showFieldError(field, field.validate(field.input.value));

       fields.forEach((field) => {
         setDescribedBy(field.input, field.helpId, field.error.id, false);

         field.input.addEventListener("blur", () => {
           validateField(field);
         });

         field.input.addEventListener("input", () => {
           if (!field.error.hidden) {
             validateField(field);
           }

           if (statusMessage.textContent) {
             statusMessage.textContent = "";
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         statusMessage.textContent = "";

         const firstInvalidField = fields.find((field) => validateField(field));

         if (firstInvalidField) {
           firstInvalidField.input.focus();
           return;
         }

         statusMessage.textContent = "Your request is ready to send. Our support team will reply soon.";
         form.reset();

         fields.forEach((field) => {
           field.error.hidden = true;
           field.error.textContent = "";
           field.input.removeAttribute("aria-invalid");
           setDescribedBy(field.input, field.helpId, field.error.id, false);
         });
       });
     </script>
   </body>
 </html>

')
